  private int x;
  public SuperClasa(){ a=2; x=calcul(); }
  public int calcul(){ return 2*a; }
  public String toString(){ return a + ", " + x; }
}
class SubClasa extends SuperClasa{
  private int y;
  public SubClasa(){ y=calcul(); }
  public int calcul(){ return 3*a; }
  public String toString(){ return super.toString() + ", " + y; }
}
class MainApp{
  public static void main(String[] args){
    SubClasa ob = new SubClasa();
    System.out.println(ob);
  }
}

